01-centering.html<pre><code>&lt;!doctype html&gt;
&lt;html lang="en"&gt;
&lt;head&gt;
&lt;meta charset="utf-8"&gt;
&lt;meta name="viewport" content="width=device-width, initial-scale=1"&gt;
&lt;title&gt;Centering three ways&lt;/title&gt;
&lt;style&gt;
  :root { font-family: system-ui, sans-serif; color-scheme: light dark; }
  body { margin: 0; padding: 16px; display: grid; gap: 16px; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); }
  .box { position: relative; height: 180px; border: 2px dashed #94a3b8; border-radius: 12px; }
  .item { padding: 12px 16px; border-radius: 8px; background: #6366f1; color: white; font-weight: 600; }

  /* 1. Grid: one line, centres on both axes */
  .grid { display: grid; place-items: center; }

  /* 2. Flexbox: centre on the main and cross axes */
  .flex { display: flex; justify-content: center; align-items: center; }

  /* 3. Absolute + transform: works when the child must sit on top of other content (badges, overlays) */
  .absolute .item { position: absolute; inset: 50% auto auto 50%; transform: translate(-50%, -50%); }
&lt;/style&gt;
&lt;/head&gt;
&lt;body&gt;
  &lt;div class="box grid" data-test="grid"&gt;&lt;div class="item"&gt;place-items: center&lt;/div&gt;&lt;/div&gt;
  &lt;div class="box flex" data-test="flex"&gt;&lt;div class="item"&gt;justify + align&lt;/div&gt;&lt;/div&gt;
  &lt;div class="box absolute" data-test="absolute"&gt;&lt;div class="item"&gt;absolute + translate&lt;/div&gt;&lt;/div&gt;
&lt;/body&gt;
&lt;/html&gt;
</code></pre>

02-holy-grail.html<pre><code>&lt;!doctype html&gt;
&lt;html lang="en"&gt;
&lt;head&gt;
&lt;meta charset="utf-8"&gt;
&lt;meta name="viewport" content="width=device-width, initial-scale=1"&gt;
&lt;title&gt;Holy grail layout&lt;/title&gt;
&lt;style&gt;
  :root { font-family: system-ui, sans-serif; }
  * { box-sizing: border-box; }
  body { margin: 0; }
  .page {
    min-height: 100dvh;                         /* dvh: correct on mobile with browser chrome */
    display: grid;
    grid-template:
      "header"  auto
      "nav"     auto
      "main"    1fr
      "aside"   auto
      "footer"  auto / 1fr;                     /* mobile first: one column, content order */
  }
  @media (min-width: 900px) {
    .page {
      grid-template:
        "header header header" auto
        "nav    main   aside"  1fr
        "footer footer footer" auto / 200px 1fr 240px;
    }
  }
  header { grid-area: header; background: #312e81; color: white; }
  nav    { grid-area: nav;    background: #e0e7ff; }
  main   { grid-area: main; }
  aside  { grid-area: aside;  background: #f1f5f9; }
  footer { grid-area: footer; background: #1e293b; color: white; }
  header, nav, main, aside, footer { padding: 16px; }
&lt;/style&gt;
&lt;/head&gt;
&lt;body&gt;
  &lt;div class="page"&gt;
    &lt;header&gt;Header&lt;/header&gt;
    &lt;nav aria-label="Main"&gt;Navigation&lt;/nav&gt;
    &lt;main&gt;&lt;h1&gt;Main content&lt;/h1&gt;&lt;p&gt;Source order = reading order = mobile order. Only the grid template changes.&lt;/p&gt;&lt;/main&gt;
    &lt;aside&gt;Sidebar&lt;/aside&gt;
    &lt;footer&gt;Footer&lt;/footer&gt;
  &lt;/div&gt;
&lt;/body&gt;
&lt;/html&gt;
</code></pre>

03-card-grid.html<pre><code>&lt;!doctype html&gt;
&lt;html lang="en"&gt;
&lt;head&gt;
&lt;meta charset="utf-8"&gt;
&lt;meta name="viewport" content="width=device-width, initial-scale=1"&gt;
&lt;title&gt;Responsive card grid&lt;/title&gt;
&lt;style&gt;
  :root { font-family: system-ui, sans-serif; }
  * { box-sizing: border-box; }
  body { margin: 0; padding: 16px; }
  .cards {
    display: grid;
    /* As many 260px+ columns as fit; never wider than the container (min() avoids overflow on tiny screens) */
    grid-template-columns: repeat(auto-fit, minmax(min(260px, 100%), 1fr));
    gap: 16px;
  }
  .card {
    display: grid;
    grid-template-rows: auto auto 1fr auto;      /* image, title, text grows, button stays at the bottom */
    border: 1px solid #e2e8f0; border-radius: 12px; overflow: hidden;
  }
  .card img { width: 100%; aspect-ratio: 16 / 9; object-fit: cover; display: block; background: #c7d2fe; }
  .card h2 { margin: 12px 16px 4px; font-size: 1.1rem; }
  .card p { margin: 0 16px; color: #475569; }
  .card a { margin: 16px; justify-self: start; padding: 8px 14px; border-radius: 8px; background: #4f46e5; color: white; text-decoration: none; }
&lt;/style&gt;
&lt;/head&gt;
&lt;body&gt;
  &lt;section class="cards" aria-label="Products"&gt;
    &lt;article class="card"&gt;&lt;img alt="" src="data:image/gif;base64,R0lGODlhAQABAAAAACw="&gt;&lt;h2&gt;Short&lt;/h2&gt;&lt;p&gt;One line.&lt;/p&gt;&lt;a href="#"&gt;Buy&lt;/a&gt;&lt;/article&gt;
    &lt;article class="card"&gt;&lt;img alt="" src="data:image/gif;base64,R0lGODlhAQABAAAAACw="&gt;&lt;h2&gt;Longer description&lt;/h2&gt;&lt;p&gt;This card has a lot more text, so it is taller, but every button in the row still lines up at the bottom of its card.&lt;/p&gt;&lt;a href="#"&gt;Buy&lt;/a&gt;&lt;/article&gt;
    &lt;article class="card"&gt;&lt;img alt="" src="data:image/gif;base64,R0lGODlhAQABAAAAACw="&gt;&lt;h2&gt;Third&lt;/h2&gt;&lt;p&gt;Medium amount of text here.&lt;/p&gt;&lt;a href="#"&gt;Buy&lt;/a&gt;&lt;/article&gt;
    &lt;article class="card"&gt;&lt;img alt="" src="data:image/gif;base64,R0lGODlhAQABAAAAACw="&gt;&lt;h2&gt;Fourth&lt;/h2&gt;&lt;p&gt;Wraps to the next row when there is no room.&lt;/p&gt;&lt;a href="#"&gt;Buy&lt;/a&gt;&lt;/article&gt;
  &lt;/section&gt;
&lt;/body&gt;
&lt;/html&gt;
</code></pre>

04-sticky-header.html<pre><code>&lt;!doctype html&gt;
&lt;html lang="en"&gt;
&lt;head&gt;
&lt;meta charset="utf-8"&gt;
&lt;meta name="viewport" content="width=device-width, initial-scale=1"&gt;
&lt;title&gt;Sticky header and sticky table header&lt;/title&gt;
&lt;style&gt;
  :root { font-family: system-ui, sans-serif; }
  body { margin: 0; }
  .site-header {
    position: sticky; top: 0; z-index: 10;            /* sticks once it reaches the top of the viewport */
    background: rgb(255 255 255 / .9); backdrop-filter: blur(8px);
    border-bottom: 1px solid #e2e8f0; padding: 12px 16px; font-weight: 700;
  }
  main { padding: 16px; }
  .scroll { max-height: 240px; overflow: auto; border: 1px solid #e2e8f0; border-radius: 8px; }
  table { border-collapse: separate; border-spacing: 0; width: 100%; }
  th { position: sticky; top: 0; background: #eef2ff; text-align: left; }   /* sticky inside the scroll container */
  th, td { padding: 8px 12px; border-bottom: 1px solid #e2e8f0; }
  /* Jump links land BELOW the sticky header instead of under it */
  html { scroll-padding-top: 56px; }
&lt;/style&gt;
&lt;/head&gt;
&lt;body&gt;
  &lt;header class="site-header"&gt;Acme Store&lt;/header&gt;
  &lt;main&gt;
    &lt;div class="scroll" tabindex="0" aria-label="Orders table"&gt;
      &lt;table&gt;
        &lt;thead&gt;&lt;tr&gt;&lt;th scope="col"&gt;Order&lt;/th&gt;&lt;th scope="col"&gt;Status&lt;/th&gt;&lt;/tr&gt;&lt;/thead&gt;
        &lt;tbody id="rows"&gt;&lt;/tbody&gt;
      &lt;/table&gt;
    &lt;/div&gt;
    &lt;div style="height: 2000px"&gt;&lt;/div&gt;
    &lt;h2 id="faq"&gt;FAQ&lt;/h2&gt;
  &lt;/main&gt;
  &lt;script&gt;
    document.getElementById("rows").innerHTML =
      Array.from({ length: 30 }, (_, i) =&gt; `&lt;tr&gt;&lt;td&gt;A-${i + 1}&lt;/td&gt;&lt;td&gt;${i % 3 ? "Shipped" : "Placed"}&lt;/td&gt;&lt;/tr&gt;`).join("");
  &lt;/script&gt;
&lt;/body&gt;
&lt;/html&gt;
</code></pre>

05-modal-dialog.html<pre><code>&lt;!doctype html&gt;
&lt;html lang="en"&gt;
&lt;head&gt;
&lt;meta charset="utf-8"&gt;
&lt;meta name="viewport" content="width=device-width, initial-scale=1"&gt;
&lt;title&gt;Accessible modal dialog&lt;/title&gt;
&lt;style&gt;
  :root { font-family: system-ui, sans-serif; }
  body { margin: 0; padding: 24px; }
  dialog { border: 0; border-radius: 16px; padding: 24px; width: min(420px, calc(100% - 32px)); box-shadow: 0 20px 60px rgb(0 0 0 / .3); }
  dialog::backdrop { background: rgb(15 23 42 / .6); backdrop-filter: blur(2px); }
  dialog[open] { animation: pop .15s ease-out; }
  @keyframes pop { from { opacity: 0; transform: translateY(8px) scale(.98); } }
  @media (prefers-reduced-motion: reduce) { dialog[open] { animation: none; } }
  .actions { display: flex; gap: 8px; justify-content: flex-end; margin-top: 16px; }
  button { padding: 8px 14px; border-radius: 8px; border: 1px solid #cbd5e1; background: white; font: inherit; }
  button.primary { background: #4f46e5; color: white; border-color: #4f46e5; }
&lt;/style&gt;
&lt;/head&gt;
&lt;body&gt;
  &lt;button id="open" type="button"&gt;Delete account…&lt;/button&gt;
  &lt;p id="result" aria-live="polite"&gt;&lt;/p&gt;

  &lt;!-- &lt;dialog&gt; + showModal(): focus moves inside, the rest of the page is inert, Esc closes, top layer (no z-index wars) --&gt;
  &lt;dialog id="confirm" aria-labelledby="confirm-title" aria-describedby="confirm-desc"&gt;
    &lt;form method="dialog"&gt;
      &lt;h2 id="confirm-title"&gt;Delete account?&lt;/h2&gt;
      &lt;p id="confirm-desc"&gt;This permanently removes your data.&lt;/p&gt;
      &lt;label&gt;Type DELETE to confirm &lt;input name="confirm" autocomplete="off" autofocus&gt;&lt;/label&gt;
      &lt;div class="actions"&gt;
        &lt;button value="cancel" formnovalidate&gt;Cancel&lt;/button&gt;
        &lt;button value="delete" class="primary"&gt;Delete&lt;/button&gt;
      &lt;/div&gt;
    &lt;/form&gt;
  &lt;/dialog&gt;

  &lt;script&gt;
    const dialog = document.getElementById("confirm");
    const opener = document.getElementById("open");
    opener.addEventListener("click", () =&gt; dialog.showModal());
    // Click on the backdrop (the dialog element itself, outside the form) closes it
    dialog.addEventListener("click", (e) =&gt; { if (e.target === dialog) dialog.close("cancel"); });
    dialog.addEventListener("close", () =&gt; {
      const ok = dialog.returnValue === "delete" &amp;&amp; dialog.querySelector("input").value === "DELETE";
      document.getElementById("result").textContent = ok ? "Account deleted" : "Cancelled";
      dialog.querySelector("form").reset();
      opener.focus();                                   // return focus to what opened it
    });
  &lt;/script&gt;
&lt;/body&gt;
&lt;/html&gt;
</code></pre>

06-tabs.html<pre><code>&lt;!doctype html&gt;
&lt;html lang="en"&gt;
&lt;head&gt;
&lt;meta charset="utf-8"&gt;
&lt;meta name="viewport" content="width=device-width, initial-scale=1"&gt;
&lt;title&gt;Accessible tabs&lt;/title&gt;
&lt;style&gt;
  :root { font-family: system-ui, sans-serif; }
  body { margin: 0; padding: 24px; }
